INSERT OR IGNORE INTO posts (id, slug, title, excerpt, content, cover_url, category, status, author_id, meta_description, created_at, updated_at, published_at) VALUES ('post_chatour-travel-kediri', 'chatour-travel-kediri', 'Chatour Travel Kediri — Agen Umroh & Haji di Badas, Kediri', 'Chatour Travel Kediri melayani pendaftaran Umroh & Haji di Badas, Kabupaten Kediri. Kantor agen di Jl. Joko Sembung, hubungi 0851 9912 4487.', 'Chatour Travel Kediri adalah kantor agen Chatour Travel di wilayah Kediri, Jawa Timur. Berlokasi di Badas, agen ini melayani pendaftaran dan konsultasi paket Umroh dan Haji untuk jamaah di Kediri dan sekitarnya, dengan dukungan penuh dari kantor pusat Chatour Travel di Gresik.

## Alamat dan Kontak Chatour Travel Kediri

Kantor agen berada di Jl. Joko Sembung, Sembung, Tunglur, Kec. Badas, Kabupaten Kediri, Jawa Timur 64222. Telepon dan WhatsApp: 0851 9912 4487. Jam layanan Senin sampai Sabtu pukul 06.00 sampai 21.00 WIB. Lokasi kantor dapat ditemukan di Google Maps dengan mencari Chatour Travel Badas.

## Paket Umroh dan Haji yang Dilayani

Chatour Travel Kediri melayani pendaftaran paket Umroh Reguler, Umroh Plus, Umroh Ramadhan, Haji Reguler, dan Haji Khusus. Harga dan jadwal keberangkatan menyusul, hubungi agen melalui WhatsApp untuk informasi terbaru. Setiap paket didampingi pembimbing dan tour leader bersertifikat BNSP.

## Kenapa Memilih Chatour Travel Kediri?

Chatour Travel beroperasi sejak 2008 dan berizin resmi PPIU 81202142726030005 serta PIHK 81202142726030006. Jaringannya mencakup 400 agen resmi di seluruh Indonesia, dengan penerbangan langsung dan hotel dekat Masjidil Haram dan Masjid Nabawi. Jamaah di Kediri dapat berkonsultasi langsung dengan agen setempat tanpa harus datang ke kantor pusat di Gresik.

## Cara Daftar Lewat Agen Kediri

Hubungi agen melalui WhatsApp 0851 9912 4487 atau datang langsung ke kantor di Jl. Joko Sembung, Badas. Setelah memilih paket, siapkan paspor dan dokumen yang diperlukan, tim agen membantu melengkapinya. Selanjutnya ikuti bimbingan manasik, lalu berangkat bersama rombongan.', '', 'Info', 'published', NULL, 'Chatour Travel Kediri — agen Umroh & Haji di Badas, Kediri. Alamat Jl. Joko Sembung, telepon 0851 9912 4487, Senin–Sabtu 06.00–21.00 WIB.', '2026-11-17T12:10:00.000Z', '2026-11-17T12:10:00.000Z', '2026-11-17T12:10:00.000Z');
